package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the role each sheet gives a user name: clerk (any name with none) or steward. */
@Service
public class RoleService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheets;
    private final Audit audit;

    public RoleService(SheetRoleRepository roles, SheetRepository sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<SheetRole> list(String sheetId) {
        requireSheet(sheetId);
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public SheetRole set(String sheetId, String user, String name, String role) {
        requireSheet(sheetId);
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
        if (row == null) {
            try {
                row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
            } catch (DataIntegrityViolationException e) {
                throw new RoleConflictException();
            }
        } else {
            row.setRole(role);
            row = roles.saveAndFlush(row);
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role);
        return row;
    }

    /** Whether the sheet makes the user name a steward. */
    @Transactional(readOnly = true)
    public boolean isSteward(String sheetId, String name) {
        return roles.findBySheetIdAndUserName(sheetId, name)
                .map(r -> SheetRole.STEWARD.equals(r.getRole()))
                .orElse(false);
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
    }
}
    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or
     *  after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** How a claim dated on a date rounds its figures: half up before the policy date (the sheet's today
     *  when it has none), half to even on or after it. */
    public RoundingMode rounding(LocalDate date) {
        LocalDate policy = policyDate == null ? today : policyDate;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The late charge on an overdue claim's figure: the late percent of it for every full 30 days past its
     *  due-by (its date plus the terms) on the sheet's today, rounded to cents as its date rounds; 0.00 for no
     *  figure (n/a). Only an OPEN claim is overdue, so the caller asks only for those. */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate date) {
        long late = ChronoUnit.DAYS.between(date.plusDays(terms), today);
        if (figure == null || late < 30) {
            return BigDecimal.ZERO.setScale(2);
        }
        return figure.multiply(latePct).multiply(BigDecimal.valueOf(late / 30)).movePointLeft(2)
                .setScale(2, rounding(date));
    }

    /** A live due as it counts: at least the floor; none (n/a) stays none. */
    public BigDecimal floored(BigDecimal due) {
        return due == null ? null : due.max(floor);
    }

    /** Give out the sheet's next claim number. */
    public String nextClaimNumber() {
        return String.valueOf(++lastClaimNumber);
    }
}
package net.officefloor.hq.app.claim;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The user who opened a claim asked to settle it: a claim needs a second pair of eyes to be settled. */
@ResponseStatus(HttpStatus.CONFLICT)
public class ClaimSettlerException extends RuntimeException {

    public ClaimSettlerException() {
        super("The user who opened a claim cannot settle it.");
    }
}
package net.officefloor.hq.app.claim;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The claim's status does not allow the change asked for. */
@ResponseStatus(HttpStatus.CONFLICT)
public class ClaimStatusException extends RuntimeException {

    public ClaimStatusException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to + ".");
    }
}
